    "hero.searchPlaceholder": "Ieškokite adreso, miesto ar paslaugos…",
    "hero.titleStorage": "Sandėliai, mini sandėliai ir sandėliukai Baltijos šalyse",
    "hero.titleStorageHighlight": "palygink viename žemėlapyje",
    "hero.subtitleStorage": "Palygink vietos sandėliavimo partnerius pagal plotą, kainą ir prieigą. Arba išsiųsk vieną užklausą ir gauk iki 3 pasiūlymų — nemokamai ir be įsipareigojimų.",
    "hero.trustStrip": "{partners} partnerių · {cities} miestų",
    "hero.providerCta": "Ar esate paslaugų teikėjas? Prisijunkite nemokamai →",
    "hiw.feat1": "Patikrinto partnerio ženklelis",
    "hiw.feat1desc": "Partneriai, kurių registro duomenis, IBAN ir fizinę vietą patvirtinome, profilyje turi ženklelį — iš karto matai, kuriuos patikrinome.",
    "hiw.feat2": "Tikri pasiūlymai, ne reklama",
    "hiw.feat2desc": "Pasiūlymai ateina iš partnerių, kurie perskaitė tavo užklausą. Mes neparduodame tavo kontaktų dešimčiai įmonių.",
    "hiw.feat3": "Aiškios sąlygos",
    "hiw.feat3desc": "Skelbimai, užklausos ir prireikus nuomos sutartys laiko dydį, kainą ir prieigos informaciją viename vaizde.",
    "hiw.feat4": "Partnerio valdoma prieinamumo informacija",
    "hiw.feat4desc": "Partneriai patys valdo prieinamumą, kalendorius ir prieigos informaciją, kad vieša informacija būtų aktuali.",
    "hiw.heroSearch": "Ieškoti",
    "hiw.heroList": "Pridėti plotą",
    "hiw.stepsTitle": "Jūsų kelias penkiais žingsniais",
    "hiw.stepsSubtitle": "Tu pasakai, ko reikia. Mes randame paslaugų teikėjus.",
    "hiw.step1": "Ieškokite ir palyginkite sandėlius netoliese",
    "hiw.step1desc": "Įveskite vietovę ir naršykite vietos partnerių saugojimo ir sandėliavimo plotus. Palyginkite plotą, kainą ir prieigos sąlygas žemėlapyje arba sąraše.",
    "hiw.step2": "Mes randame partnerius",
    "hiw.step2desc": "Peržiūrime tavo užklausą ir atrenkame partnerius, kurie tikrai tinka — o ne tiesiog visus iš sąrašo.",
    "hiw.step3": "Gauni iki 3 pasiūlymų",
    "hiw.step3desc": "Pasiūlymai atkeliauja į tavo pašto dėžutę, kai tik partneriai atsako. Ramiai palygink kainas ir sąlygas.",
    "hiw.step4": "Pasirink ir susitark",
    "hiw.step4desc": "Bendrauk su pasirinktu partneriu tiesiogiai ir susitark dėl detalių. Klientui Ruumly nemokamas ir prie kainos nieko neprideda.",
    "hiw.step5": "Gaukite prieigą ir įsikraustykite",
    "hiw.step5desc": "Gaukite patvirtinimą ir prieigos nurodymus iš partnerio — atveškite savo daiktus ir įsikraustykite pasirinktą dieną.",
    "hiw.whySubtitle": "Aiškumas kiekviename žingsnyje — prieš ką nors įsipareigojant.",
    "hiw.partnerBadge": "Partneriams",
    "hiw.partnerTitle": "Pridėkite savo sandėlį prie Ruumly",
    "hiw.partnerDesc": "Turite laisvos sandėliavimo vietos? Patalpinkite ją Ruumly nemokamai ir pasiekite klientus, ieškančius žemėlapyje ir Google. Jūs nustatote kainas, prieinamumą ir ar norite tik užklausų, ar ir internetinio rezervavimo.",
