    "home.whyRuumly.savings": "Viena užklausa visoms kraustymosi paslaugoms — jokio skambinėjimo ratu",
    "home.whyRuumly.title": "Kodėl rinktis Ruumly?",
    "home.whyRuumly.verified": "Viena užklausa iš karto pasiekia kelis vietos paslaugų teikėjus — nemokamai ir be įsipareigojimų.",
    "homeFaq.a1": "Ieškokite sandėlio, palyginkite vietas ir kainas, tada susisiekite su partneriu. Jei partneris įjungė internetinį rezervavimą, datas ir sąlygas galite patvirtinti iš karto.",
    "homeFaq.a2": "Ne. Daugelis skelbimų prasideda nuo užklausos arba tiesioginio kontakto su partneriu. Internetinis rezervavimas, sutartis ir mokėjimas rodomi tik ten, kur partneris juos įjungė.",
