    "privacy.s1.text": "Duomenų valdytojas yra Diip Solutions OÜ (reg. nr. 17527757), Uus-Sadama tn 15-2, 10120 Talinas, Estija. Kontaktas: info@ruumly.eu.",
    "privacy.s1.title": "1. Bendra informacija",
    "privacy.s2.items": "Vardas ir kontaktinė informacija (el. paštas, telefonas)|Paskyros duomenys (vartotojo vardas, slaptažodžio maišos)|Rezervacijos duomenys ir paslaugų naudojimo istorija|Vietos duomenys (paieškoms)|Įrenginio ir naršyklės duomenys (per slapukus)|Mokėjimo duomenys (apdorojami per saugius mokėjimo tiekėjus)",
    "privacy.s2.title": "2. Kokius duomenis renkame?",
    "privacy.s3.items": "Paslaugų teikimas ir rezervacijų valdymas|Vartotojo patirties gerinimas|Marketingo komunikacija (tik su sutikimu)|Teisinių įsipareigojimų vykdymas|Platformos saugumo užtikrinimas",
    "privacy.s3.title": "3. Kaip naudojame jūsų duomenis?",
    "privacy.s4.text": "Dalijamės duomenimis su paslaugų teikėjais, mokėjimų tarpininkais ir analitikos įrankiais.",
    "privacy.s4.title": "4. Duomenų dalijimasis",
    "privacy.s5.intro": "Pagal BDAR jūs turite teisę:",
    "privacy.s5.items": "Prieiga prie jūsų asmens duomenų|Prašyti duomenų taisymo arba ištrynimo|Apriboti duomenų tvarkymą|Duomenų perkeliamumas|Pateikti skundą Duomenų apsaugos inspekcijai",
    "privacy.s5.title": "5. Jūsų teisės",
    "privacy.s6.text": "Saugome jūsų duomenis, kol turite aktyvią paskyrą arba kaip reikalauja įstatymai.",
    "privacy.s6.title": "6. Duomenų saugojimas",
    "privacy.s7.text": "Naudojame SSL šifravimą, saugius serverius ir reguliarius saugumo patikrinimus.",
    "privacy.s8.title": "7. Savideklaruoti pasirašymo duomenys",
    "privacy.s8.items": "Savideklaruoti pasirašymo duomenys: jūsų įvestas vardas ir asmens/ID kodas bei jūsų elektroninis patvirtinimas, saugomi pasirašytoje nuomos sutartyje.",
    "privacy.s9.title": "8. Pasirašytų sutarčių saugojimas",
    "privacy.s9.text": "Pasirašytos nuomos sutartys (kuriose gali būti asmens kodas) saugomos įstatymo reikalaujamą laikotarpį ir sutarčiai įrodyti, atskirai nuo paskyros ištrynimo termino.",
    "privacy.s7.title": "9. Saugumas",
