    "terms.s1.text": "Šios sąlygos reglamentuoja Ruumly platformos (ruumly.eu) naudojimą. Ruumly platformą valdo Diip Solutions OÜ (reg. nr. 17527757), Uus-Sadama tn 15-2, 10120 Talinas, Estija. Naudodamiesi platforma jūs pripažįstate, kad ji yra ankstyvame testavimo ir partnerių atsiliepimų etape; šiame etape gali vykti realūs rezervavimai ir sandoriai, įskaitant apmokėjimą banko pavedimu.",
    "terms.s1.title": "1. Bendrosios sąlygos",
    "terms.s2.text": "Ruumly yra internetinė platforma, jungianti paslaugų teikėjus su klientais.",
    "terms.s2.title": "2. Paslaugos aprašymas",
    "terms.s3.text": "Norint rezervuoti paslaugas, reikia sukurti paskyrą su galiojančiu el. pašto adresu.",
    "terms.s3.title": "3. Naudotojų paskyros",
    "terms.s4.text": "Rezervacijos yra privalomos. Kainos nurodytos su PVM.",
    "terms.s4.title": "4. Rezervacijos ir mokėjimai",
    "terms.s5.text": "Atšaukimo sąlygos priklauso nuo paslaugų teikėjo. Nemokamas atšaukimas per 24 valandas.",
    "terms.s5.title": "5. Atšaukimo politika",
    "terms.s6.text": "Ruumly veikia kaip tarpininkas, jungiantis klientus su nepriklausomais partneriais, ir nėra šalis bei neatsako už partnerių teikiamas paslaugas. Įstatymų leidžiama apimtimi Ruumly neatsako už nuostolius, atsiradusius dėl partnerio paslaugos; pretenzijos dėl paslaugos sprendžiamos tarp kliento ir partnerio.",
    "terms.s6.title": "6. Atsakomybė",
