    "testimonial.subtitle": "Tikra patirtis su Ruumly visoje Estijoje.",
    "testimonial.quote1": "Ruumly užpildė mūsų sandėliavimo vietas be nė vieno telefono skambučio. Užsakymai tiesiog ateina ir viskas aišku.",
