    "testimonial.role1": "Partneris steigėjas · Sandėliavimas, Talinas",
    "testimonial.quote2": "Vakare išsiunčiau vieną užklausą, o iki pietų jau turėjau tris pasiūlymus. Pasirinkau tinkamiausią — ir kraustymasis buvo baigtas per savaitę.",
